//! Absolute S32 level, not just waveform correlation, is independent of PCMR.
//! Original signals and opaque FFmpeg references are regenerated by
//! fixtures/generate_pcm_resolution.py. Each metadata variant has an identical
//! reference decode; 20/24-bit inputs must not gain 16x/256x or clip at i32.

use oxideav_dts::{iter_frames, CoreStreamDecoder};

fn decoded(bytes: &[u8], primaries: usize, bits: u8) -> Vec<Vec<i32>> {
    let mut decoder = CoreStreamDecoder::new(primaries);
    let channels = primaries + usize::from(primaries == 5);
    let mut result = vec![vec![]; channels];
    let mut count = 0;
    for frame in iter_frames(bytes) {
        let frame = frame.unwrap();
        assert_eq!(frame.header.source_pcm_bits_per_sample(), Some(bits));
        let pcm = decoder.decode_frame(frame.data, &frame.header).unwrap();
        assert_eq!(pcm.len(), primaries);
        for (destination, plane) in result.iter_mut().zip(pcm) {
            destination.extend(plane);
        }
        let lfe = decoder.take_last_lfe_pcm();
        if primaries == 5 {
            assert_eq!(lfe.len(), 512);
            result[5].extend(lfe);
        } else {
            assert!(lfe.is_empty());
        }
        count += 1;
    }
    assert_eq!(count, 8);
    result
}

#[cfg(feature = "registry")]
fn registry_pcm(bytes: &[u8], channels: usize) -> Vec<Vec<i32>> {
    use oxideav_core::{CodecId, CodecParameters, Frame, Packet, TimeBase};
    let parameters = CodecParameters::audio(CodecId::new("dts"));
    let mut decoder = oxideav_dts::make_decoder(&parameters).unwrap();
    let mut result = vec![vec![]; channels];
    for (index, frame) in iter_frames(bytes).enumerate() {
        let frame = frame.unwrap();
        let mut packet = Packet::new(0, TimeBase::new(1, 48000), frame.data.to_vec());
        packet.pts = Some(index as i64 * 512);
        decoder.send_packet(&packet).unwrap();
        let Frame::Audio(frame) = decoder.receive_frame().unwrap() else {
            panic!("DTS must return audio");
        };
        assert_eq!(frame.pts, packet.pts);
        assert_eq!(frame.samples, 512);
        assert_eq!(frame.data.len(), channels);
        for (destination, plane) in result.iter_mut().zip(frame.data) {
            assert_eq!(plane.len(), 512 * 4, "full-scale planar S32");
            destination.extend(
                plane
                    .chunks_exact(4)
                    .map(|sample| i32::from_le_bytes(sample.try_into().unwrap())),
            );
        }
    }
    result
}

fn check_variants(variants: &[(&[u8], u8)], reference: &[u8], primaries: usize) {
    // Native 5.1 order is C L R SL SR LFE; FFmpeg is L R C LFE SL SR.
    let order: &[usize] = if primaries == 5 {
        &[2, 0, 1, 4, 5, 3]
    } else {
        &[0, 1]
    };
    let channels = order.len();
    let mut expected = vec![vec![]; channels];
    for (index, sample) in reference.chunks_exact(4).enumerate() {
        expected[index % channels].push(i32::from_le_bytes(sample.try_into().unwrap()));
    }
    let mut baseline = None;
    for &(bytes, bits) in variants {
        let actual = decoded(bytes, primaries, bits);
        #[cfg(feature = "registry")]
        assert_eq!(
            registry_pcm(bytes, channels),
            actual,
            "registry S32 contract"
        );
        for (native, &reference_channel) in order.iter().enumerate() {
            let a = &actual[native];
            let r = &expected[reference_channel];
            assert_eq!(a.len(), 4096);
            assert_eq!(r.len(), a.len());
            let signal: f64 = r.iter().map(|&s| (s as f64).powi(2)).sum();
            let error: f64 = a
                .iter()
                .zip(r)
                .map(|(&a, &r)| (a as f64 - r as f64).powi(2))
                .sum();
            let energy: f64 = a.iter().map(|&s| (s as f64).powi(2)).sum();
            let relative_rmse = (error / signal).sqrt();
            let gain = (energy / signal).sqrt();
            assert!(signal > 1e15, "non-silent independent channel oracle");
            assert!(
                relative_rmse < 3e-5,
                "PCMR {bits} channel {native}: relative RMSE {relative_rmse}"
            );
            assert!(
                (gain - 1.0).abs() < 1e-5,
                "PCMR {bits} channel {native}: absolute gain {gain}"
            );
            assert!(
                a.iter().all(|&s| s != i32::MIN && s != i32::MAX),
                "PCMR {bits} clipped channel {native}"
            );
        }
        if let Some(baseline) = &baseline {
            assert_eq!(&actual, baseline, "source precision changed decoded PCM");
        } else {
            baseline = Some(actual);
        }
    }
}

#[test]
fn stereo_source_precisions_preserve_full_scale_s32_level() {
    check_variants(
        &[
            (include_bytes!("fixtures/pcmr_stereo_16.dts"), 16),
            (include_bytes!("fixtures/pcmr_stereo_20.dts"), 20),
            (include_bytes!("fixtures/pcmr_stereo_24.dts"), 24),
        ],
        include_bytes!("fixtures/pcmr_stereo_ffmpeg.s32"),
        2,
    );
}

#[test]
fn five_one_source_precisions_preserve_each_primary_and_lfe_level() {
    check_variants(
        &[
            (include_bytes!("fixtures/pcmr_51_16.dts"), 16),
            (include_bytes!("fixtures/pcmr_51_20.dts"), 20),
            (include_bytes!("fixtures/pcmr_51_24.dts"), 24),
        ],
        include_bytes!("fixtures/pcmr_51_ffmpeg.s32"),
        5,
    );
}
